// MIT. Wire shapes for the existing Cryptoworth accountant workflow.
export const CRYPTOWORTH_TOOL_PREFIX='merchant_accounting_cryptoworth_';
export const CRYPTOWORTH_CLIENT_OPERATION_SCHEMA='stellar-forge.accounting-cryptoworth-operation.v1';
export const CRYPTOWORTH_FILE_SELECTORS=['profileId','captureId','returnId','rollbackId','scope'];
export const cryptoworthFileName={type:'string',pattern:'^[A-Za-z0-9][A-Za-z0-9._-]{0,239}$'};
const text={type:'string',maxLength:4000},alias={type:'string',pattern:'^[a-z0-9][a-z0-9_-]{0,63}$'};
export const cryptoworthNativeId={type:'string',pattern:'^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$'};
const nativeId=cryptoworthNativeId,sha={type:'string',pattern:'^[a-f0-9]{64}$'};
const nullableId={anyOf:[nativeId,{type:'null'}]},instant={type:'string',minLength:1,maxLength:80};
const object=(properties,required=[],additionalProperties=false)=>({type:'object',properties,required,additionalProperties});
const page={offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:200}};
const filter={...page,status:{type:'string',maxLength:100},search:{type:'string',maxLength:500}};
const workspace={workspace:alias},bound={...workspace,workspaceId:sha};
const revision={type:'integer',minimum:1},who={id:nativeId,name:{type:'string',minLength:1,maxLength:240},actor:{type:'string',minLength:1,maxLength:1000},createdAt:instant};
const sourceFile=object({source:alias,name:{type:'string',minLength:1,maxLength:240},sha256:sha,bytes:{type:'integer',minimum:0,maximum:134217728}},['source','name']);
const roles=['date','cryptoId','type','amountOne','amountOneType','amountTwo','amountTwoType','transactionHash','connectionId','note','ledgerId','rowId'];
const columns=object(Object.fromEntries(roles.map(role=>[role,{type:'string',minLength:1,maxLength:1000}])));
const date=object({format:{type:'string',enum:['ISO_UTC','UTC_SECONDS','UTC_DATE','ZONE_SECONDS','ZONE_DATE']},timeZone:{type:'string',minLength:1,maxLength:100},precision:{type:'string',enum:['day','second','millisecond']}},['format','timeZone']);
const target=object({entityId:text,entityName:text,connectionId:text,connectionName:text,merchantAccount:text},['entityId','connectionId','merchantAccount']);
const profile={...who,previousProfileId:nullableId,file:sourceFile,delimiter:{type:'string',enum:[',',';','\t']},columns,
  constants:object({},[],true),target,date,assets:{type:'array',minItems:1,maxItems:500,items:object({
    network:{type:'string',enum:['stellar:testnet','stellar:pubnet']},assetDigest:sha,cryptoId:text,amountType:text,scale:{type:'integer',minimum:0,maximum:30}},
    ['network','assetDigest','cryptoId','amountType','scale'])}};
const plan={...who,profileId:nativeId,handoffId:nativeId,accountantRevisionId:{anyOf:[nativeId,{type:'string',enum:['initial']}]},previousPlanId:nullableId,
  decisions:{type:'array',maxItems:50000,items:object({movementId:sha,selectionId:{anyOf:[sha,{type:'null'}]},action:{type:'string',enum:['INCLUDE','EXCLUDE','ALREADY_IMPORTED']},reason:text,reference:text},['movementId','action'])},
  dateEvidence:{type:'array',maxItems:5000,items:object({movementId:sha,transferAt:instant,note:text,file:sourceFile},['movementId','transferAt','note','file'])}};
const nativeImport=object({id:text,entityId:text,connectionId:text,receivedAt:instant,reference:text,note:text},['id','entityId','connectionId','receivedAt','reference']);
const capture={...who,purpose:{type:'string',enum:['IMPORT_RETURN','BASELINE']},file:sourceFile,nativeImport,layout:object({
  kind:{type:'string',enum:['INPUT_FORMAT','MAPPED_EXPORT']},delimiter:{type:'string',enum:[',',';','\t']},columns,date,
  amountConvention:{type:'string',enum:['UNSIGNED','SEND_NEGATIVE']},amountTwoConvention:{type:'string',enum:['UNSIGNED','SEND_NEGATIVE']},groupSeparator:{type:'string',enum:['',',']}},['kind'])};
const returned={...who,captureId:nativeId,status:{type:'string',enum:['REVIEWED','BOOKED']},bookRef:text,
  accountCode:{anyOf:[text,{type:'null'}]},note:text,expectedParentId:nullableId};
export const CRYPTOWORTH_REQUEST_FIELDS={profile:Object.keys(profile),plan:Object.keys(plan),capture:Object.keys(capture),return:Object.keys(returned)};
const requests={profile,plan,capture,return:returned};
const required={profile:['name','actor','file','columns','constants','target','date','assets'],plan:['name','actor','profileId','handoffId','accountantRevisionId'],
  capture:['name','actor','purpose','file','nativeImport','layout'],return:['name','actor','captureId','status','expectedParentId']};
const readOnly={readOnly:true,idempotent:true};
export const cryptoworthDefinitions=[
  [CRYPTOWORTH_TOOL_PREFIX+'status','Read this original Cryptoworth owner, workspace ID and revision. Page saved mappings, receiving plans, original handoffs or complete import-unit rollbacks.',{...workspace,view:{type:'string',enum:['summary','profiles','plans','handoffs','rollbacks']},...page},['workspace'],readOnly],
  [CRYPTOWORTH_TOOL_PREFIX+'source','Page the selected frozen original handoff and native payment/refund source. Keep accountantRevisionId explicit; initial selects the unchanged first handoff.',{...workspace,handoffId:nativeId,accountantRevisionId:{anyOf:[nativeId,{type:'string',enum:['initial']}]},...filter},['workspace','handoffId','accountantRevisionId'],readOnly],
  [CRYPTOWORTH_TOOL_PREFIX+'template','Inspect the actual customer-supplied native template from one configured input alias. Returns exact filename, byte count and SHA256 for review.',{...workspace,file:sourceFile,delimiter:{type:'string',enum:[',',';','\t']}},['workspace','file'],readOnly],
  ...Object.keys(requests).flatMap(kind=>[
    [CRYPTOWORTH_TOOL_PREFIX+kind+'_preview','Review the original '+kind+' operation. File aliases are expanded using actual bytes and returned with exact hashes; keep the complete normalized request, workspace ID, revision and native preview hash.',
      {...workspace,...(['capture','return'].includes(kind)?{planId:nativeId}:{}),request:object(requests[kind],required[kind]),...(['plan','capture'].includes(kind)?filter:{})},
      ['workspace',...(['capture','return'].includes(kind)?['planId']:[]),'request'],{readOnly:true}],
    [CRYPTOWORTH_TOOL_PREFIX+kind+'_save','Save the exact reviewed original '+kind+' request. Preserve the native ID, timestamp, file hashes, workspace ID and preview hash. A retained native ID recovers the original outcome; no new payment or vendor import is initiated.',
      {...bound,...(['capture','return'].includes(kind)?{planId:nativeId}:{}),request:object({...requests[kind],revision,previewSha256:sha},[...required[kind],'id','createdAt','revision','previewSha256'])},
      ['workspace','workspaceId',...(['capture','return'].includes(kind)?['planId']:[]),'request'],{idempotent:true}]
  ]),
  [CRYPTOWORTH_TOOL_PREFIX+'profile','Read one exact retained mapping, source template identity and original files.',{...workspace,profileId:nativeId},['workspace','profileId'],readOnly],
  [CRYPTOWORTH_TOOL_PREFIX+'plan','Read one retained receiving plan or page its captures, returns, rollbacks, files, prior packet receipts, decisions or native date sources.',{...workspace,planId:nativeId,view:{type:'string',enum:['summary','captures','returns','rollbacks','files','receivedPackets','decisions','dateEvidence']},...page},['workspace','planId'],readOnly],
  [CRYPTOWORTH_TOOL_PREFIX+'rows','Page exact source/import rows or a selected native receiving comparison without changing their atomic amounts, signs or opaque native IDs.',{...workspace,planId:nativeId,captureId:nativeId,...filter},['workspace','planId'],readOnly],
  [CRYPTOWORTH_TOOL_PREFIX+'capture','Read one saved native receiving capture, its source bytes, comparison summary and import-unit rollbacks.',{...workspace,planId:nativeId,captureId:nativeId},['workspace','planId','captureId'],readOnly],
  [CRYPTOWORTH_TOOL_PREFIX+'return','Read the original staged, committed or superseded accountant return by native ID. PREPARED keeps the exact request available for continuation; COMMITTED and SUPERSEDED are terminal outcomes.',{...workspace,planId:nativeId,returnId:nativeId},['workspace','planId','returnId'],readOnly],
  [CRYPTOWORTH_TOOL_PREFIX+'rollback','Record an already completed rollback of the entire selected native import unit. This updates original receiving coverage; the operator supplies the real vendor completion time and reference.',
    {...bound,planId:nativeId,request:object({id:nativeId,captureId:nativeId,nativeImportId:text,completedAt:instant,actor:{...text,maxLength:1000},reason:text,reference:text,revision},['id','captureId','nativeImportId','completedAt','actor','reason','reference','revision'])},
    ['workspace','workspaceId','planId','request'],{idempotent:true}],
  [CRYPTOWORTH_TOOL_PREFIX+'rollback_record','Read one exact saved native import-unit rollback.',{...workspace,rollbackId:nativeId},['workspace','rollbackId'],readOnly],
  [CRYPTOWORTH_TOOL_PREFIX+'packet_inspect','Inspect a complete original receiving packet from a configured source alias. Rebuild its original template, source, native comparison, accountant returns and coverage before returning its exact two hashes.',{...workspace,file:sourceFile},['workspace','file'],readOnly],
  [CRYPTOWORTH_TOOL_PREFIX+'packet_receive','Receive the exact reviewed source packet in this original owner. Pin the input SHA256 and sealed packet SHA256. Existing native IDs retain their original history and source files.',
    {...bound,file:sourceFile,revision,actor:{...text,maxLength:1000},name:{...text,maxLength:240},expectedSha256:sha,expectedPacketSha256:sha},
    ['workspace','workspaceId','file','revision','actor','expectedSha256','expectedPacketSha256'],{idempotent:true}],
];

export function cryptoworthPreviewBinding(value){return {kind:value.kind,workspaceId:value.workspaceId,planId:value.planId??null,request:value.request,workspaceRevision:value.workspaceRevision,previewSha256:value.previewSha256,requestSha256:value.requestSha256};}

export type JsonValue = string | number | boolean | null | JsonValue[] | { [key: string]: JsonValue };
export type JsonObject = { [key: string]: JsonValue };
export type WorkspaceAlias = string;
export type UUID = string;
export type SHA256 = string;
export type NativeAction =
 | 'source_refresh' | 'offer_prepare' | 'offer_publish' | 'offer_adopt' | 'order_prepare' | 'order_adopt'
 | 'start' | 'stop' | 'attach_pass' | 'access' | 'recover_call' | 'release_call'
 | 'export_usage' | 'export_result' | 'backup' | 'restore';
export type Collection = 'offers' | 'orders' | 'operations' | 'exports' | 'backups' | 'functions';
export interface RequestOptions { requestSignal?: AbortSignal | null; timeoutMs?: number }
export type StructuredMcpCall = (name: string, args: JsonObject, options?: RequestOptions) => Promise<unknown>;
export interface ConnectionOptions {
 url: string; tokenEnv?: string; environment?: Record<string, string | undefined>; signal?: AbortSignal;
 workspace: WorkspaceAlias; workspaceId?: UUID;
}
export interface ClientOptions {
 workspace: WorkspaceAlias; workspaceId: UUID; call: StructuredMcpCall; endpoint?: string;
}
export interface Mutation { operationId: UUID; expectedRevision: number }
export interface Route { id: string; functionId: string; units: number; timeoutSeconds: number }
export interface OfferSpecification { title: string; allowanceUnits: number; routes: Route[]; workerPort: number; apiPort: number }
export interface OrderSelection { offerId: UUID; orderReference: string; label: string }
export interface CallSelection { offerId: UUID; orderReference: string; requestId: string; callRevision: number; reason: string }
export type AccessChange =
 | { orderReference: string; accessRevision: number; action: 'expire'; reason: string; expiresAt: string }
 | { orderReference: string; accessRevision: number; action: 'suspend' | 'resume' | 'clear-expiry'; reason: string; expiresAt?: null };
export interface ActionArguments {
 source_refresh: Mutation;
 offer_prepare: Mutation & OfferSpecification & { expectedSourceSha256: SHA256 };
 offer_publish: Mutation & { offerId: UUID };
 offer_adopt: Mutation & { application: string; label: string };
 order_prepare: Mutation & OrderSelection;
 order_adopt: Mutation & OrderSelection;
 start: Mutation & { offerId: UUID };
 stop: Mutation;
 attach_pass: Mutation & { orderReference: string };
 access: Mutation & AccessChange;
 recover_call: Mutation & CallSelection;
 release_call: Mutation & CallSelection;
 export_usage: Mutation & { orderReference: string };
 export_result: Mutation & { offerId: UUID; executionId: string };
 backup: Mutation & { offerId: UUID; label: string; resumeService: boolean };
 restore: Mutation & { backupId: UUID; label: string };
}
export interface NativeOperation {
 id: UUID; kind: NativeAction; status: 'QUEUED' | 'RUNNING' | 'COMPLETED' | 'ATTENTION' | 'CANCELLED';
 requestSha256: SHA256; createdAt: string; updatedAt: string;
 attempts: JsonObject[]; result: JsonValue; error: JsonValue;
 request?: JsonObject;
}
export interface Acceptance { operation: NativeOperation; workspaceRevision: number; replayed?: boolean }
export interface WorkspaceSummary {
 workspace: string; workspaceId: UUID; label: string; configSha256: SHA256;
 applications: Array<{ handle: string; label: string; profileFileSha256: SHA256; planFileSha256: SHA256 }>;
 receiving: Array<{ handle: string; label: string; metadataSha256: SHA256 }>;
 files: unknown;
}
export interface WorkspaceInventory { configured: boolean; closing: boolean; pendingRequests: number; workspaces: WorkspaceSummary[] }
export interface WorkspaceView {
 workspaceId: UUID; revision: number; source: JsonObject; fault: JsonValue; service: JsonValue;
 counts: Record<Collection, number>;
}
export interface InventoryPage {
 workspaceId: UUID; collection: Collection; revision: number; offset: number; limit: number;
 total: number; nextOffset: number | null; items: JsonObject[];
}
export interface CompleteInventory {
 workspaceId: UUID; collection: Collection; revision: number; total: number; items: JsonObject[];
}
export interface FileMetadata { name: string; bytes: number; sha256: SHA256; contentType: string }
export interface NativeManifest {
 schema: 'stellar-forge.sf101.api-merchant-export.v1'; id: UUID; exportId: UUID;
 kind: string; label: string; createdAt: string;
 files: Array<FileMetadata & { path: string }>;
}
export interface RetainedManifest {
 state: 'MANIFEST_RETAINED'; exportId: UUID; workspaceId: UUID;
 kind: string; label: string; createdAt: string; manifestFile: FileMetadata; files: FileMetadata[];
}
export interface ReadFileArguments {
 exportId: UUID; file: string; expectedManifestSha256: SHA256; expectedSha256: SHA256;
 readId?: UUID; offset?: number; limit?: number;
}
export interface FileChunk {
 exportId: UUID; manifestSha256: SHA256; readId: UUID; file: FileMetadata;
 offset: number; bytesRead: number; nextOffset: number | null; encoding: 'base64'; data: string;
}
export interface DownloadOptions {
 exportId: UUID; directory: string; expectedManifestSha256?: SHA256; signal?: AbortSignal; chunkSize?: number;
 onProgress?: (progress: { exportId: UUID; file: string; bytes: number; total: number; state: 'DOWNLOADING' }) => void | Promise<void>;
}
export interface HttpDownloadOptions extends DownloadOptions {
 workspace: WorkspaceAlias; workspaceId: UUID; url: string; tokenEnv?: string;
 environment?: Record<string, string | undefined>;
}
export interface DownloadResult {
 schema: 'stellar-forge.sf101.api-merchant-mcp-download.v1'; state: 'COMPLETE' | 'REOPENED';
 directory: string; exportId: UUID; workspace: WorkspaceAlias; workspaceId: UUID; kind: string; label: string;
 manifestSha256: SHA256; files: number; bytes: number; resumed?: boolean; resumedBytes?: number;
}
export interface ApiMerchantWorkspaceClient {
 readonly workspace: WorkspaceAlias; readonly workspaceId: UUID; readonly endpoint?: string;
 invoke(kind: string, args?: JsonObject, options?: RequestOptions): Promise<JsonObject>;
 view(args?: Record<string, never>, options?: RequestOptions): Promise<WorkspaceView>;
 inventory(args: { collection: Collection; offset?: number; limit?: number; expectedRevision?: number }, options?: RequestOptions): Promise<InventoryPage>;
 allInventory(collection: Collection, options?: RequestOptions): Promise<CompleteInventory>;
 selections(args?: Record<string, never>, options?: RequestOptions): Promise<{ applications: JsonObject[]; receiving: JsonObject[] }>;
 preview(args: OfferSpecification, options?: RequestOptions): Promise<JsonObject & { sourceSha256: SHA256 }>;
 refreshSource(args: ActionArguments['source_refresh'], options?: RequestOptions): Promise<Acceptance>;
 prepareOffer(args: ActionArguments['offer_prepare'], options?: RequestOptions): Promise<Acceptance>;
 publishOffer(args: ActionArguments['offer_publish'], options?: RequestOptions): Promise<Acceptance>;
 adoptOffer(args: ActionArguments['offer_adopt'], options?: RequestOptions): Promise<Acceptance>;
 prepareOrder(args: ActionArguments['order_prepare'], options?: RequestOptions): Promise<Acceptance>;
 adoptOrder(args: ActionArguments['order_adopt'], options?: RequestOptions): Promise<Acceptance>;
 start(args: ActionArguments['start'], options?: RequestOptions): Promise<Acceptance>;
 stop(args: ActionArguments['stop'], options?: RequestOptions): Promise<Acceptance>;
 attachPass(args: ActionArguments['attach_pass'], options?: RequestOptions): Promise<Acceptance>;
 updateAccess(args: ActionArguments['access'], options?: RequestOptions): Promise<Acceptance>;
 recoverCall(args: ActionArguments['recover_call'], options?: RequestOptions): Promise<Acceptance>;
 releaseCall(args: ActionArguments['release_call'], options?: RequestOptions): Promise<Acceptance>;
 exportUsage(args: ActionArguments['export_usage'], options?: RequestOptions): Promise<Acceptance>;
 exportResult(args: ActionArguments['export_result'], options?: RequestOptions): Promise<Acceptance>;
 backup(args: ActionArguments['backup'], options?: RequestOptions): Promise<Acceptance>;
 restore(args: ActionArguments['restore'], options?: RequestOptions): Promise<Acceptance>;
 run<K extends NativeAction>(kind: K, args: ActionArguments[K], options?: RequestOptions): Promise<NativeOperation>;
 waitOperation(args: { operationId: UUID; requestSha256?: SHA256; pollIntervalMs?: number }, options?: RequestOptions): Promise<NativeOperation>;
 operation(args: { operationId: UUID }, options?: RequestOptions): Promise<NativeOperation>;
 resume(args: { operationId: UUID; requestSha256: SHA256 }, options?: RequestOptions): Promise<Acceptance>;
 cancel(args: { operationId: UUID; requestSha256: SHA256 }, options?: RequestOptions): Promise<NativeOperation>;
 offer(args: { offerId: UUID }, options?: RequestOptions): Promise<JsonObject>;
 order(args: { orderReference: string; after?: string; limit?: number }, options?: RequestOptions): Promise<JsonObject>;
 executions(args: { offerId: UUID; after?: string; limit?: number }, options?: RequestOptions): Promise<JsonObject>;
 execution(args: { offerId: UUID; executionId: string }, options?: RequestOptions): Promise<JsonObject>;
 manifest(args: { exportId: UUID }, options?: RequestOptions): Promise<RetainedManifest>;
 readFileChunk(args: ReadFileArguments, options?: RequestOptions): Promise<FileChunk>;
 releaseFile(args: { exportId: UUID; readId: UUID }, options?: RequestOptions): Promise<{ exportId: UUID; readId: UUID; released: true }>;
 restoreBundle(args: { receiving: string; expectedMetadataSha256: SHA256 }, options?: RequestOptions): Promise<JsonObject>;
 downloadExport(options: DownloadOptions): Promise<DownloadResult>;
 disconnect(): Promise<void>;
}
export function discoverApiMerchantWorkspaces(options: { call: StructuredMcpCall }): Promise<WorkspaceInventory>;
export function createApiMerchantWorkspaceClient(options: ClientOptions): Readonly<ApiMerchantWorkspaceClient>;
export function connectApiMerchantWorkspaceClient(options: ConnectionOptions): Promise<Readonly<ApiMerchantWorkspaceClient>>;
export function downloadApiMerchantExport(options: HttpDownloadOptions): Promise<DownloadResult>;
export function inspectApiMerchantExportDownload(options: Omit<HttpDownloadOptions, 'directory' | 'expectedManifestSha256' | 'chunkSize' | 'onProgress'>): Promise<{ manifest: NativeManifest; manifestSha256: SHA256 }>;
export function reopenApiMerchantExportDownload(options: {
 directory: string; expectedManifestSha256?: SHA256; workspace: WorkspaceAlias; workspaceId: UUID; endpoint?: string;
}): Promise<DownloadResult>;

// MIT. Typed control and complete native receiving through the original merchant MCP.
import {join} from 'node:path';
import {createHash} from 'node:crypto';
import {setTimeout as delay} from 'node:timers/promises';
import {openMerchantFileClient,createRetainedDownload} from './retained-download.mjs';
import {
 API_MERCHANT_PREFIX,API_MERCHANT_ALIAS,API_MERCHANT_UUID,API_MERCHANT_HASH,API_MERCHANT_ACTIONS,
 API_MERCHANT_MANIFEST,API_MERCHANT_MAX_FILE_BYTES,API_MERCHANT_MAX_MANIFEST_BYTES,
 apiMerchantPlain,apiMerchantNeed,apiMerchantArguments,parseApiMerchantExport,
} from './api-merchant-protocol.mjs';
const DOWNLOAD_STATE='stellar-forge.sf101.api-merchant-mcp-download-state.v1';
const DOWNLOAD_RESULT='stellar-forge.sf101.api-merchant-mcp-download.v1';
const METHODS={
 view:'view',inventory:'inventory',selections:'selections',preview:'preview',refreshSource:'source_refresh',
 prepareOffer:'offer_prepare',publishOffer:'offer_publish',adoptOffer:'offer_adopt',
 prepareOrder:'order_prepare',adoptOrder:'order_adopt',start:'start',stop:'stop',attachPass:'attach_pass',
 updateAccess:'access',recoverCall:'recover_call',releaseCall:'release_call',exportUsage:'export_usage',
 exportResult:'export_result',backup:'backup',restore:'restore',operation:'operation',resume:'resume',cancel:'cancel',
 offer:'offer',order:'order',executions:'executions',execution:'execution',manifest:'manifest',readFileChunk:'file',
 releaseFile:'file_release',restoreBundle:'restore_bundle',
};
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
function binding(workspace,workspaceId){
 apiMerchantNeed(typeof workspace==='string'&&typeof workspaceId==='string'&&API_MERCHANT_ALIAS.test(workspace)&&API_MERCHANT_UUID.test(workspaceId),
  'Select the alias and original workspace ID returned by merchant_api_console_workspaces.','API_MERCHANT_CLIENT_CONFIGURATION');
 return '#api-merchant-workspace='+encodeURIComponent(workspace)+'&workspace-id='+workspaceId;
}
function nativeReply(result,workspace,workspaceId){
 apiMerchantNeed(apiMerchantPlain(result)&&result.workspace===workspace&&result.workspaceId===workspaceId&&apiMerchantPlain(result.native),
  'The reply must belong to this selected original merchant workspace.','API_MERCHANT_CLIENT_WORKSPACE_CHANGED');
 return result.native;
}
function transfer({workspace,workspaceId,connect}){
 const suffix=binding(workspace,workspaceId);
 return createRetainedDownload({
  manifestName:API_MERCHANT_MANIFEST,parseManifest:parseApiMerchantExport,maximumBytes:API_MERCHANT_MAX_FILE_BYTES,
  maximumManifestBytes:API_MERCHANT_MAX_MANIFEST_BYTES,maximumCheckpointBytes:1024*1024,
  stateSchema:DOWNLOAD_STATE,resultSchema:DOWNLOAD_RESULT,toolPrefix:API_MERCHANT_PREFIX.slice(0,-1),
  errorPrefix:'API_MERCHANT_AGENT',clientName:'starforge-api-merchant-receiving',
  validateExportId:value=>apiMerchantNeed(API_MERCHANT_UUID.test(value??''),'Select an original export ID.','API_MERCHANT_CLIENT_EXPORT_REQUIRED'),
  describe:manifest=>({workspace,workspaceId,kind:manifest.kind,label:manifest.label,createdAt:manifest.createdAt}),
  connect:connect??(async options=>{
   const transport=await openMerchantFileClient(options);
   return {endpoint:transport.endpoint+suffix,async call(name,args,request){
    return nativeReply(await transport.call(name,apiMerchantArguments(name,{...args,workspace}),request),workspace,workspaceId);
   }};
  }),
 });
}
/** Read source-owned aliases without opening another native merchant workspace. */
export async function discoverApiMerchantWorkspaces({call}={}){
 apiMerchantNeed(typeof call==='function','Supply the existing structured MCP caller.','API_MERCHANT_CLIENT_CONFIGURATION');
 const result=await call(API_MERCHANT_PREFIX+'workspaces',{});
 apiMerchantNeed(apiMerchantPlain(result)&&Array.isArray(result.workspaces)&&result.workspaces.every(item=>
  apiMerchantPlain(item)&&API_MERCHANT_ALIAS.test(item.workspace??'')&&API_MERCHANT_UUID.test(item.workspaceId??'')),
  'The original provider must return its configured workspace aliases.','API_MERCHANT_CLIENT_CONFIGURATION');
 return result;
}
/** The caller drains its accepted requests; the original console retains native ownership. */
export function createApiMerchantWorkspaceClient({workspace,workspaceId,call,endpoint}={}){
 const suffix=binding(workspace,workspaceId);
 apiMerchantNeed(typeof call==='function','Supply the existing structured MCP caller.','API_MERCHANT_CLIENT_CONFIGURATION');
 let closing=false,closePromise;const pending=new Set();
 function captured(kind,input={}){
  apiMerchantNeed(apiMerchantPlain(input)&&!Object.hasOwn(input,'workspace'),'Use this caller’s selected workspace.');
  const {workspace:alias,...request}=apiMerchantArguments(kind,{...input,workspace});return request;
 }
 async function wire(kind,input={},options){
  apiMerchantNeed(apiMerchantPlain(input)&&!Object.hasOwn(input,'workspace'),'Use this caller’s selected workspace.');
  const args=apiMerchantArguments(kind,{...input,workspace}),name=kind.startsWith(API_MERCHANT_PREFIX)?kind:API_MERCHANT_PREFIX+kind;
  return nativeReply(await call(name,args,options),workspace,workspaceId);
 }
 function tracked(work){
  apiMerchantNeed(!closing,'This caller is draining or closed.','API_MERCHANT_CLIENT_CLOSING');
  const promise=Promise.resolve().then(work);pending.add(promise);promise.finally(()=>pending.delete(promise)).catch(()=>{});return promise;
 }
 async function settledOperation({operationId,requestSha256,pollIntervalMs=350},options={}){
  apiMerchantNeed(API_MERCHANT_UUID.test(operationId??'')&&(requestSha256===undefined||API_MERCHANT_HASH.test(requestSha256))&&
   Number.isSafeInteger(pollIntervalMs)&&pollIntervalMs>=100&&pollIntervalMs<=60000,
   'Retain the original operation ID, optional request SHA and a polling interval.','API_MERCHANT_CLIENT_OPERATION_REQUIRED');
  for(;;){
   options.requestSignal?.throwIfAborted();
   const result=await wire('operation',{operationId},options);
   apiMerchantNeed(result.id===operationId&&(requestSha256===undefined||result.requestSha256===requestSha256),
    'The original saved operation request changed.','API_MERCHANT_CLIENT_OPERATION_CHANGED');
   if(['COMPLETED','ATTENTION','CANCELLED'].includes(result.status))return result;
   apiMerchantNeed(['QUEUED','RUNNING'].includes(result.status),'The original operation state is unavailable.','API_MERCHANT_CLIENT_OPERATION_CHANGED');
   await delay(pollIntervalMs,undefined,{signal:options.requestSignal??undefined});
  }
 }
 const client={workspace,workspaceId,endpoint,
  invoke:(kind,args={},options)=>{
   const request=captured(kind,args),settings={...options};return tracked(()=>wire(kind,request,settings));
  },
  waitOperation:(args,options)=>{
   apiMerchantNeed(apiMerchantPlain(args),'Supply the retained operation selection.','API_MERCHANT_CLIENT_OPERATION_REQUIRED');
   const request={...args},settings={...options};return tracked(()=>settledOperation(request,settings));
  },
  run:(kind,args,options)=>{
   apiMerchantNeed(API_MERCHANT_ACTIONS.includes(kind),'Choose one of the native durable actions.','API_MERCHANT_CLIENT_OPERATION_REQUIRED');
   const request=captured(kind,args),settings={...options};
