:root{color-scheme:light;--bg:#f4f4f4;--surface:#ffffff;--soft:#f8f8f8;--line:#d3d3d3;--ink:#212121;--muted:#656565;--strong:#373737;--focus:#171717;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;font-size:14px;line-height:1.55}
