.notice.error{border-width:2px;background:#eeeeee}
.callout{padding:13px 15px;background:#f2f2f2;border-left:3px solid #5f5f5f;margin:14px 0;overflow-wrap:anywhere}
.callout strong{display:block;margin-bottom:4px}
.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px 18px}
.form-grid.three{grid-template-columns:repeat(3,minmax(0,1fr))}
.form-grid .full{grid-column:1/-1}
.field{display:flex;flex-direction:column;min-width:0;gap:5px;margin-bottom:14px}
.form-grid .field{margin-bottom:0}
.field>label,.field>.field-label{font-size:12px;font-weight:650}
input:not([type=checkbox]),select,textarea{width:100%;border:1px solid #b2b2b2;border-radius:2px;background:#ffffff;color:var(--ink);padding:8px 10px;min-height:37px}
textarea{resize:vertical;min-height:85px;line-height:1.5}
input[readonly],textarea[readonly]{background:#f1f1f1;color:#606060}
input[type=checkbox]{width:17px;height:17px;vertical-align:middle;accent-color:#4a4a4a}
.checkbox-label{display:flex;gap:9px;align-items:flex-start;font-size:12px}
.checkbox-label input{flex:none;margin:2px 0 0}
.hint{font-size:11px;color:#666666;margin:0}
.form-actions{padding-top:16px;margin-top:16px;border-top:1px solid var(--line)}
.draft-status{font-size:11px;color:#6c6c6c;margin:8px 0}
.route-card{padding:15px;background:#fbfbfb;border:1px solid var(--line);margin:14px 0}
.route-card-header{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:13px}
.route-card-header h4{margin:0}
.route-source{padding:10px 0 0;font-size:12px;color:#636363}
.list{list-style:none;padding:0;margin:0}
.list>li{padding:12px 0;border-bottom:1px solid var(--line)}
.list>li:last-child{border-bottom:0}
.list h4{margin-bottom:4px}
.split{display:grid;grid-template-columns:minmax(0,2fr) minmax(250px,1fr);gap:20px}
.split>*{min-width:0}
.break{overflow-wrap:anywhere;word-break:break-word}
.inset{margin:14px 0;padding:14px;background:#f6f6f6;border:1px solid var(--line)}
.search-row{display:flex;gap:12px;align-items:flex-end;margin-bottom:15px}
.search-row>.field{max-width:500px;flex:1;margin:0}
.connect-panel{max-width:640px;margin:50px auto;padding:28px;background:#ffffff;border:1px solid var(--line)}
.connect-panel form{display:grid;grid-template-columns:1fr auto;gap:10px;align-items:center}
.connect-panel label{grid-column:1/-1;font-weight:650;font-size:12px}
.footer{padding:16px 28px;border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap;color:#6e6e6e;font-size:11px;background:#f5f5f5}
