  // 39-digit policy ceilings even when higher than the Soroban i128 maximum.
  const maxText = typeof maxAtomic === 'string' ? maxAtomic :
    (typeof maxAtomic === 'number' && Number.isSafeInteger(maxAtomic) && maxAtomic > 0) ?
      String(maxAtomic) :
