          ['FINALIZED','IDEMPOTENT_FINALIZED','NOT_FINALIZED','WORKER_ERROR','RESERVATION_VERIFIED'].includes(result.outcome)&&
          (code===0||code===2),'INBOX_FINALIZATION_RESULT_INVALID');
